// Talara's Battalion
// status: ready
// Cast this spell only if you've cast another green spell this turn.
// Trample
#[allow(unused_imports)] use cantrip_api::*;
fn ability_0_if(q: &dyn Query, asker: &Asker) -> bool { (q.history().this_turn().iter().filter_map(|r: &Record| -> Option<Fired> { let event = &r.event; if let Event::SpellCast { spell, player, .. } = event { let id = *spell; let subject = Target::Object(id); let data = [u32::from(player.0), u32::MAX]; if Some(asker.controller) == Some(*player) && (!(Some(asker.source) == Some(id)) && q.chars(id).colors.has(q.words(asker.source).color(Color::Green))) { return Some(Fired { subject, data }); } }  None }).count() as i64) >= (1i64) }

